script:
export const meta = {
  name: 'W913-再复审',
  description: 'W913 再复审（预审之复）：一攻者只攻复审所纳之十三防与总编辑之裁 → 须改则纳防再定（⛔施）',
  phases: [
    { title: '再复审', detail: '一攻者' },
    { title: '定', detail: '须改方跑' },
  ],
}
const S = '/tmp/claude-0/-home-user/fc87a25e-bbf0-5a31-be3f-8a53382aa0f0'
const WT = S + '/scratchpad/wt913'
const PLAN = WT + '/设定/方案/W913.md'
const ENV = `
【境】施工之树：${WT}（主枝 9e2b48095 之上；方案 ${PLAN} 已提交 6ff2e12ef·约 128KB）。首审之果：${S}/tasks/wndp1z0y3.output；复审之果（二攻者 13 险俱纳）：${S}/tasks/wio474e5w.output（result.atks 与 result.fin）。
另：章料.人物() 之知截已由 治 dc9a1c8c9 先治（首尾之截·不在本树·⛔复报其截）。总编辑 1120 裁：任单三件之取舍照环2 之定（⛔交作者）。
⛔git commit/push/checkout/stash/reset；⛔动 /home/user/the-novel 与他树；试於 /tmp 之副本，试毕必删（rm -rf）。零 token 之器只读只跑。文风：仓之文风。
质之铁律：⛔伤书之质、⛔拖累写书（写书之坐之读每席 ≤千字）。480 在写；W913 唯 480 封後入主，首用之章以「首章 F」之常量定。
预算紧（作者本周余 25%）：只报真险、要害，⛔细碎。`
const RISKS = { type: 'object', properties: {
  risks: { type: 'array', description: 'risks', items: { type: 'object', properties: {
    risk: { type: 'string', description: '险' }, ring: { type: 'string', description: '环N 或 取' },
    evidence: { type: 'string', description: '据（档:行、实跑之令与其果）' }, defense: { type: 'string', description: '防（可施、有锚）' } },
    required: ['risk', 'ring', 'evidence', 'defense'] } },
  verdict: { type: 'string', description: '判：可施／须改（书其由）' } }, required: ['risks', 'verdict'] }

phase('再复审')
const atk = await agent(`${ENV}
【汝之职】再复审之攻者（只读）：复审所纳之十三防（见复审之果 fin.gist 与其 atks），逐条对方案今文——防是否真落於其环、落而生新病否（改与改相撞、与既有之器相悖、首章 F／首段 S 之常量於诸器是否一把、收证以「片」之验是否可施、回放取 git archive 之全树是否可行、图之核.md 之另顶与裁席之读、记令6 之在场之人之源、剧情庭.js 补单之接线）。可於 /tmp 副本实跑诸器以证。
只报真险（至多 6 条）：每险有据（档:行或实跑之果）、有可施之防（有锚、⛔以否定起首）；⛔复述已防且今文确已落者。无真险即 risks 空、判「可施」。`, { label: '再复审:十三防', phase: '再复审', schema: RISKS })

if (!atk || !atk.risks || atk.risks.length === 0) { return { atk, fin: null } }
phase('定')
const fin = await agent(`${ENV}
【汝之职】定：纳再复审之防於方案 ${PLAN}（只改此档）。再复审之果：${JSON.stringify(atk)}
一、逐险或纳（改其环之文：做什么、确证、败则）或驳（书由於注）。
二、「## 预审」一节：预审者之行改作「- 预审者：wf_33599ddb-aed、wf_3c935b8b-2d0、wf_再复审待补（首审攻者 3；复审攻者 2；再复审攻者 1）」；再复审每险各添一行，式照既有之险行「- 险（环N｜取）：…｜防：…」（防⛔以否定起首、须有锚）；判之行照「须改→已改 环…」之式并入所改之环。
三、改毕跑 cd ${WT} && python3 工具/方案.py --预审之指 W913，以其所印更「- 审之指：」之行；再跑 python3 工具/方案.py --验 W913 须 ✓（「wf_再复审待补」致之坏可许——书之）。
四、⛔改他档；/tmp 之副本必删。返：所纳、所驳（由）、验之果。`, { label: '定:W913', phase: '定', schema: { type: 'object', properties: {
  adopted: { type: 'number', description: '纳' }, rejected: { type: 'number', description: '驳' }, gist: { type: 'string', description: '要' } }, required: ['adopted', 'rejected', 'gist'] } })
return { atk, fin }
